discrete EnergyHarvestingSystem
port:
    event input real StartCommand;
    event input real SufficientEnergyDetected;
    event input real StopCommand;
    event output real EnergyProvided;
state:
    initial state Standby
        when entry() then
            statehold(5);
        end;
        when receive(StartCommand) then
            transition(Running);
        end;
        when receive(SufficientEnergyDetected) then
            transition(Running);
        end;
    end;

    state Running
        when entry() then
            statehold(10);
        end;
        when receive(StopCommand) then
            transition(Standby);
        end;
        when !receive(SufficientEnergyDetected) then
            transition(Standby);
        end;
    end;
end;
end;

discrete EnergyStorageSystem
port:
    event input real SufficientEnergyForStorage;
    event input real HighPowerDemand;
    event input real PowerDemandMet;
    event output real EnergyStored;
    event output real EnergyReleased;
state:
    initial state Idle
        when entry() then
            statehold(5);
        end;
        when receive(SufficientEnergyForStorage) then
            transition(Charging);
        end;
    end;

    state Charging
        when entry() then
            statehold(10);
        end;
        when receive(HighPowerDemand) then
            transition(Discharging);
        end;
        when !receive(SufficientEnergyForStorage) then
            transition(Idle);
        end;
    end;

    state Discharging
        when entry() then
            statehold(10);
        end;
        when receive(PowerDemandMet) then
            transition(Idle);
        end;
        when !receive(HighPowerDemand) then
            transition(Charging);
        end;
    end;
end;
end;

discrete EnergyDistributionSystem
port:
    event input real TotalPowerDemandExceedsCapacity;
    event input real PowerSupplyRestored;
    event output real ReserveCalled;
state:
    initial state NormalPowerSupply
        when entry() then
            statehold(5);
        end;
        when receive(TotalPowerDemandExceedsCapacity) then
            transition(CallingReserve);
        end;
    end;

    state CallingReserve
        when entry() then
            statehold(10);
        end;
        when receive(PowerSupplyRestored) then
            transition(NormalPowerSupply);
        end;
    end;
end;
end;

couple MultiEnergySystem
import architectureModels.EnergyHarvestingSystem as EHS;
import architectureModels.EnergyStorageSystem as ESS;
import architectureModels.EnergyDistributionSystem as EDS;
part:
    EHS HarvestingInstance;
    ESS StorageInstance;
    EDS DistributionInstance;
connection:
    connect(HarvestingInstance.EnergyProvided, StorageInstance.SufficientEnergyForStorage);
    connect(StorageInstance.EnergyStored, DistributionInstance.TotalPowerDemandExceedsCapacity);
    connect(DistributionInstance.ReserveCalled, StorageInstance.HighPowerDemand);
end;
